-- Add six original, reviewed themes so the public store spans all nine
-- supported categories. The active global theme and instance selections do
-- not change; new designs enter only through the existing preview/release flow.


UPDATE theme_versions SET review_status='approved',approved_by='system',approved_at=now()
WHERE theme_id IN ('cobalt-arcade','terracotta-house','monsoon-garden','paper-lantern','snowlight-minimal','kesar-royale');

-- Keep the daily rotation pointed only at reviewed packages. No new theme is
-- published by this migration and the active theme remains Obsidian Hall.
UPDATE theme_release_schedule SET rotation_version_ids=ARRAY[
  'obsidian-hall-v1','midnight-indigo-v1','marigold-festival-v1',
  'cobalt-arcade-v1','terracotta-house-v1','monsoon-garden-v1',
  'paper-lantern-v1','snowlight-minimal-v1','kesar-royale-v1'
] WHERE singleton=true;
