INSERT INTO theme_catalog(theme_id,name,description,category,status,created_by,approved_by,approved_at) VALUES
 ('cobalt-arcade','Cobalt Arcade','A crisp blue-hour game lounge with electric azure calls, cool paper tickets, and a high-clarity number board.','premium','approved','system','system',now()),
 ('terracotta-house','Terracotta House','An earthy heritage palette inspired by clay courtyards, carved wood, and warm cream ticket stock.','traditional','approved','system','system',now()),
 ('monsoon-garden','Monsoon Garden','A rain-washed garden of deep teal surfaces, jade highlights, and softly rounded game-night panels.','seasonal','approved','system','system',now()),
 ('paper-lantern','Paper Lantern','A festive plum-and-rose celebration with lantern-bright accents and a distinct warm ticket face.','celebration','approved','system','system',now()),
 ('snowlight-minimal','Snowlight Minimal','A quiet slate-and-frost interface with square geometry, restrained shadows, and clean number contrast.','minimal','approved','system','system',now()),
 ('kesar-royale','Kesar Royale','A rich aubergine hall with saffron-gold details, formal serif display type, and luminous ivory tickets.','special','approved','system','system',now());
